CREATE OR REPLACE FUNCTION public.finish_group_session_daily(p_group_session_id uuid, p_athlete_id uuid, p_seconds integer)
 RETURNS TABLE(message text, athlete_id uuid, daily_finish_seconds integer, previous_pb_seconds integer, new_pb_seconds integer, is_new_pb boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  session_row public.coach_group_sessions%rowtype;
  old_pb integer;
  seconds_value integer := greatest(0, coalesce(p_seconds, 0));
  pb_changed boolean := false;
begin
  if auth.uid() is null then
    raise exception 'Not authenticated';
  end if;

  select cgs.* into session_row
  from public.coach_group_sessions cgs
  where cgs.id = p_group_session_id;

  if session_row.id is null then
    raise exception 'Group session not found';
  end if;

  if not (
    session_row.coach_id = auth.uid()
    or exists (
      select 1
      from public.profiles p
      where p.id = auth.uid()
        and p.role in ('coach', 'admin')
    )
  ) then
    raise exception 'Only the coach can finish rider Daily timers';
  end if;

  select p.daily_pb_seconds into old_pb
  from public.profiles p
  where p.id = p_athlete_id;

  update public.coach_group_session_participants cgsp
  set daily_finished_at = now(),
      daily_finish_seconds = seconds_value,
      last_activity_at = now()
  where cgsp.group_session_id = p_group_session_id
    and cgsp.athlete_id = p_athlete_id;

  if old_pb is null or seconds_value < old_pb then
    update public.profiles p
    set daily_pb_seconds = seconds_value,
        daily_pb_updated_at = now(),
        updated_at = now()
    where p.id = p_athlete_id;
    pb_changed := true;
  end if;

  return query
  select
    (case when pb_changed then 'New Daily PB' else 'Daily finish time saved' end)::text as message,
    p_athlete_id as athlete_id,
    seconds_value as daily_finish_seconds,
    old_pb as previous_pb_seconds,
    coalesce((select p.daily_pb_seconds from public.profiles p where p.id = p_athlete_id), seconds_value) as new_pb_seconds,
    pb_changed as is_new_pb;
end;
$function$

CREATE OR REPLACE FUNCTION public.record_assignment_action(p_assignment_id uuid, p_action text DEFAULT 'landed'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_uid uuid := auth.uid();
  v_assignment public.weekly_trick_assignments%rowtype;
  v_actor_role public.user_role;
  v_can_manage boolean := false;
  v_actor_is_athlete boolean := false;
  v_session public.training_sessions%rowtype;
  v_group_session public.coach_group_sessions%rowtype;
  v_progress public.assignment_progress%rowtype;
  v_today date;
  v_points integer := 0;
  v_removed_points integer := 0;
  v_deleted_award record;
  v_message text := '';
  v_award_key text;
  v_daily_venue text := '';
  v_daily_complete_key text := '';
  v_daily_under_20_key text := '';
  v_daily_legacy_key text := '';
  v_all_daily_done boolean := false;
  v_has_live_session boolean := false;
  v_elapsed_seconds integer := 0;
  v_group_pause_seconds integer := 0;
begin
  if v_uid is null then
    raise exception 'Sign in required';
  end if;

  select wta.* into v_assignment
  from public.weekly_trick_assignments wta
  where wta.id = p_assignment_id
    and wta.category in ('daily','dialled','one_bang','foam_pit','bonus');
  if not found then
    raise exception 'Assigned trick not found';
  end if;

  select p.role into v_actor_role
  from public.profiles p
  where p.id = v_uid;

  v_actor_is_athlete := v_assignment.athlete_id = v_uid;
  v_can_manage := v_actor_is_athlete
    or (
      v_actor_role in ('coach', 'admin')
      and exists (
        select 1
        from public.coach_athletes ca
        where ca.coach_id = v_uid
          and ca.athlete_id = v_assignment.athlete_id
      )
    );

  if not v_can_manage then
    raise exception 'You cannot update this rider''s tricks';
  end if;

  select b.local_today into v_today
  from public.profiles p
  cross join lateral public.jkcrew_week_bounds(p.country_code) b
  where p.id = v_assignment.athlete_id;

  if v_today is null then
    v_today := (now() at time zone 'Australia/Brisbane')::date;
  end if;

  if p_action not in ('landed', 'unlanded') then
    raise exception 'Unknown action';
  end if;

  v_daily_venue := coalesce(nullif(trim(v_assignment.venue), ''), 'default');
  v_daily_complete_key := 'daily-complete:' || v_daily_venue || ':' || v_today::text;
  v_daily_under_20_key := 'daily-under-20:' || v_daily_venue || ':' || v_today::text;
  v_daily_legacy_key := 'daily:' || v_daily_venue || ':' || v_today::text;

  select ts.* into v_session
  from public.training_sessions ts
  where ts.athlete_id = v_assignment.athlete_id
    and ts.ended_at is null
  order by ts.started_at desc
  limit 1;
  v_has_live_session := found;

  if v_has_live_session then
    select cgs.* into v_group_session
    from public.coach_group_session_participants cgsp
    join public.coach_group_sessions cgs on cgs.id = cgsp.group_session_id
    where cgsp.training_session_id = v_session.id
    order by cgs.started_at desc
    limit 1;

    if found then
      v_group_pause_seconds := coalesce(v_group_session.total_paused_seconds, 0)
        + case
          when v_group_session.status = 'paused' and v_group_session.paused_at is not null
            then greatest(0, extract(epoch from (now() - v_group_session.paused_at))::integer)
          else 0
        end;
      v_elapsed_seconds := greatest(0, extract(epoch from (now() - v_group_session.started_at))::integer - v_group_pause_seconds);
      v_has_live_session := v_group_session.status = 'running';
    else
      v_elapsed_seconds := greatest(0, extract(epoch from (now() - v_session.started_at))::integer);
    end if;
  end if;

  insert into public.assignment_progress (assignment_id, athlete_id)
  values (v_assignment.id, v_assignment.athlete_id)
  on conflict (assignment_id) do nothing;

  if p_action = 'unlanded' then
    if v_assignment.category = 'daily' then
      -- Daily checklist state resets/changes independently from earned score.
      -- Once the full list has awarded daily-complete or under-20 points for a
      -- local date, never remove those earned point awards from an untick.
      v_removed_points := 0;

      update public.assignment_progress ap
      set progress_date = null,
          updated_at = now()
      where ap.assignment_id = v_assignment.id
      returning ap.* into v_progress;

      v_message := 'Daily trick unticked';
    else
      v_award_key := v_assignment.category || ':' || v_assignment.id::text;

      for v_deleted_award in
        delete from public.assignment_point_awards apa
        where apa.athlete_id = v_assignment.athlete_id
          and apa.award_key = v_award_key
        returning apa.points, apa.session_id
      loop
        v_removed_points := v_removed_points + coalesce(v_deleted_award.points, 0);
        if v_deleted_award.session_id is not null then
          update public.training_sessions ts
          set total_points = greatest(0, coalesce(ts.total_points, 0) - coalesce(v_deleted_award.points, 0))
          where ts.id = v_deleted_award.session_id;
        end if;
      end loop;

      update public.assignment_progress ap
      set completed_at = null,
          streak_count = case when v_assignment.category = 'dialled' then 0 else ap.streak_count end,
          updated_at = now()
      where ap.assignment_id = v_assignment.id
      returning ap.* into v_progress;

      v_message := case
        when v_assignment.category = 'dialled' then 'Dialled trick unticked'
        when v_assignment.category = 'foam_pit' then 'Foam Pit trick unticked'
        when v_assignment.category = 'bonus' then 'Bonus Trick unticked'
        else 'One Bang unticked'
      end;
    end if;

    if v_session.id is not null then
      delete from public.trick_attempts ta
      where ta.id in (
        select ta2.id
        from public.trick_attempts ta2
        where ta2.session_id = v_session.id
          and ta2.athlete_id = v_assignment.athlete_id
          and ta2.category = v_assignment.category
          and ta2.trick_name = v_assignment.trick_name
        order by ta2.created_at desc
        limit 1
      );
    end if;

    if v_group_session.id is not null then
      update public.coach_group_session_participants cgsp
      set last_activity_at = now()
      where cgsp.group_session_id = v_group_session.id
        and cgsp.athlete_id = v_assignment.athlete_id;
    end if;

    select ap.* into v_progress
    from public.assignment_progress ap
    where ap.assignment_id = v_assignment.id;

    return jsonb_build_object(
      'assignment_id', v_assignment.id,
      'category', v_assignment.category,
      'venue', v_assignment.venue,
      'progress_date', v_progress.progress_date,
      'streak_count', v_progress.streak_count,
      'completed_at', v_progress.completed_at,
      'points_awarded', 0,
      'points_removed', coalesce(v_removed_points, 0),
      'message', v_message,
      'live_session', v_has_live_session,
      'elapsed_seconds', v_elapsed_seconds
    );
  end if;

  if v_assignment.category = 'daily' then
    update public.assignment_progress ap
    set progress_date = v_today,
        updated_at = now()
    where ap.assignment_id = v_assignment.id
    returning ap.* into v_progress;

    select not exists (
      select 1
      from public.weekly_trick_assignments a
      left join public.assignment_progress ap on ap.assignment_id = a.id
      where a.athlete_id = v_assignment.athlete_id
        and a.week_start = v_assignment.week_start
        and a.category = 'daily'
        and coalesce(nullif(trim(a.venue), ''), 'default') = v_daily_venue
        and ap.progress_date is distinct from v_today
    ) into v_all_daily_done;

    if v_all_daily_done then
      if not exists (
        select 1
        from public.assignment_point_awards apa
        where apa.athlete_id = v_assignment.athlete_id
          and apa.award_key in (v_daily_complete_key, v_daily_legacy_key)
      ) then
        insert into public.assignment_point_awards (athlete_id, session_id, assignment_id, award_key, points)
        values (
          v_assignment.athlete_id,
          case when v_session.id is not null then v_session.id else null end,
          v_assignment.id,
          v_daily_complete_key,
          1
        )
        on conflict (athlete_id, award_key) do nothing;
        if found then
          v_points := v_points + 1;
        end if;
      end if;

      if v_has_live_session and v_elapsed_seconds <= 1200 then
        insert into public.assignment_point_awards (athlete_id, session_id, assignment_id, award_key, points)
        values (v_assignment.athlete_id, v_session.id, v_assignment.id, v_daily_under_20_key, 1)
        on conflict (athlete_id, award_key) do nothing;
        if found then
          v_points := v_points + 1;
        end if;
      end if;

      if v_group_session.id is not null and v_group_session.status = 'running' then
        v_award_key := 'group-first-finish:' || v_group_session.id::text;
        if not exists (
          select 1
          from public.assignment_point_awards apa
          where apa.award_key = v_award_key
        ) then
          insert into public.assignment_point_awards (athlete_id, session_id, assignment_id, award_key, points)
          values (v_assignment.athlete_id, v_session.id, v_assignment.id, v_award_key, 1)
          on conflict (athlete_id, award_key) do nothing;
          if found then
            v_points := v_points + 1;
          end if;
        end if;
      end if;
    end if;

    v_message := case
      when v_points >= 3 then 'Daily Tricks complete, under 20 minutes, and first in the group'
      when v_points = 2 and v_has_live_session and v_elapsed_seconds <= 1200 then 'Daily Tricks complete inside 20 minutes'
      when v_points = 2 then 'Daily Tricks complete plus first finish bonus'
      when v_points = 1 and v_all_daily_done then 'Daily Tricks list complete'
      when v_has_live_session then 'Daily trick ticked'
      else 'Daily progress saved outside a live session'
    end;

  elsif v_assignment.category = 'one_bang' then
    update public.assignment_progress ap
    set completed_at = coalesce(ap.completed_at, now()),
        updated_at = now()
    where ap.assignment_id = v_assignment.id
    returning ap.* into v_progress;

    v_award_key := 'one_bang:' || v_assignment.id::text;
    insert into public.assignment_point_awards (athlete_id, session_id, assignment_id, award_key, points)
    values (v_assignment.athlete_id, case when v_session.id is not null then v_session.id else null end, v_assignment.id, v_award_key, 2)
    on conflict (athlete_id, award_key) do nothing;
    if found then
      v_points := 2;
    end if;
    v_message := 'One Bang complete';

  elsif v_assignment.category = 'dialled' then
    update public.assignment_progress ap
    set completed_at = coalesce(ap.completed_at, now()),
        streak_count = 1,
        updated_at = now()
    where ap.assignment_id = v_assignment.id
    returning ap.* into v_progress;

    v_award_key := 'dialled:' || v_assignment.id::text;
    insert into public.assignment_point_awards (athlete_id, session_id, assignment_id, award_key, points)
    values (v_assignment.athlete_id, case when v_session.id is not null then v_session.id else null end, v_assignment.id, v_award_key, 2)
    on conflict (athlete_id, award_key) do nothing;
    if found then
      v_points := 2;
    end if;
    v_message := 'Dialled trick complete';

  elsif v_assignment.category = 'bonus' then
    update public.assignment_progress ap
    set completed_at = coalesce(ap.completed_at, now()),
        updated_at = now()
    where ap.assignment_id = v_assignment.id
    returning ap.* into v_progress;

    v_award_key := 'bonus:' || v_assignment.id::text;
    insert into public.assignment_point_awards (athlete_id, session_id, assignment_id, award_key, points)
    values (v_assignment.athlete_id, case when v_session.id is not null then v_session.id else null end, v_assignment.id, v_award_key, 5)
    on conflict (athlete_id, award_key) do nothing;
    if found then
      v_points := 5;
    end if;
    v_message := 'Bonus Trick complete';

  elsif v_assignment.category = 'foam_pit' then
    update public.assignment_progress ap
    set completed_at = coalesce(ap.completed_at, now()),
        updated_at = now()
    where ap.assignment_id = v_assignment.id
    returning ap.* into v_progress;

    v_points := 0;
    v_message := 'Foam Pit practice ticked';
  end if;

  if v_session.id is not null then
    insert into public.trick_attempts (session_id, athlete_id, trick_name, category, status, duration_seconds, points)
    values (v_session.id, v_assignment.athlete_id, v_assignment.trick_name, v_assignment.category, 'landed', v_elapsed_seconds, v_points);

    if v_points > 0 then
      update public.training_sessions ts
      set total_points = coalesce(ts.total_points, 0) + v_points
      where ts.id = v_session.id;
    end if;
  end if;

  if v_group_session.id is not null then
    update public.coach_group_session_participants cgsp
    set last_activity_at = now()
    where cgsp.group_session_id = v_group_session.id
      and cgsp.athlete_id = v_assignment.athlete_id;
  end if;

  select ap.* into v_progress
  from public.assignment_progress ap
  where ap.assignment_id = v_assignment.id;

  return jsonb_build_object(
    'assignment_id', v_assignment.id,
    'category', v_assignment.category,
    'venue', v_assignment.venue,
    'progress_date', v_progress.progress_date,
    'streak_count', v_progress.streak_count,
    'completed_at', v_progress.completed_at,
    'points_awarded', v_points,
    'points_removed', 0,
    'message', v_message,
    'live_session', v_has_live_session,
    'elapsed_seconds', v_elapsed_seconds
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.record_assignment_action_at_venue(p_assignment_id uuid, p_action text DEFAULT 'landed'::text, p_venue text DEFAULT ''::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  perform set_config('jkcrew.venue', coalesce(btrim(p_venue), ''), true);
  return public.record_assignment_action(p_assignment_id, p_action);
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_daily_completion_timing()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_assignment public.weekly_trick_assignments%rowtype;
  v_today date;
  v_daily_venue text := 'default';
  v_all_daily_done boolean := false;
  v_session public.training_sessions%rowtype;
  v_group_session public.coach_group_sessions%rowtype;
  v_elapsed_seconds integer := 0;
  v_group_pause_seconds integer := 0;
  v_old_pb integer;
begin
  if tg_op = 'DELETE' or new.progress_date is null then
    return new;
  end if;

  select wta.* into v_assignment
  from public.weekly_trick_assignments wta
  where wta.id = new.assignment_id
    and wta.category = 'daily';

  if not found then
    return new;
  end if;

  v_today := new.progress_date;
  v_daily_venue := coalesce(nullif(trim(v_assignment.venue), ''), 'default');

  select not exists (
    select 1
    from public.weekly_trick_assignments wta
    left join public.assignment_progress ap on ap.assignment_id = wta.id
    where wta.athlete_id = v_assignment.athlete_id
      and wta.week_start = v_assignment.week_start
      and wta.category = 'daily'
      and coalesce(nullif(trim(wta.venue), ''), 'default') = v_daily_venue
      and ap.progress_date is distinct from v_today
  ) into v_all_daily_done;

  if not v_all_daily_done then
    return new;
  end if;

  select ts.* into v_session
  from public.training_sessions ts
  where ts.athlete_id = v_assignment.athlete_id
    and ts.ended_at is null
  order by ts.started_at desc
  limit 1;

  if not found then
    return new;
  end if;

  select cgs.* into v_group_session
  from public.coach_group_session_participants cgsp
  join public.coach_group_sessions cgs on cgs.id = cgsp.group_session_id
  where cgsp.training_session_id = v_session.id
  order by cgs.started_at desc
  limit 1;

  if found then
    v_group_pause_seconds := coalesce(v_group_session.total_paused_seconds, 0)
      + case
        when v_group_session.status = 'paused' and v_group_session.paused_at is not null
          then greatest(0, extract(epoch from (now() - v_group_session.paused_at))::integer)
        else 0
      end;
    v_elapsed_seconds := greatest(0, extract(epoch from (now() - v_group_session.started_at))::integer - v_group_pause_seconds);
  else
    v_elapsed_seconds := greatest(0, extract(epoch from (now() - v_session.started_at))::integer);
  end if;

  update public.training_sessions ts
  set daily_completed_seconds = case
        when ts.daily_completed_seconds is null then v_elapsed_seconds
        else least(ts.daily_completed_seconds, v_elapsed_seconds)
      end,
      daily_completed_at = coalesce(ts.daily_completed_at, now())
  where ts.id = v_session.id;

  if v_group_session.id is not null then
    update public.coach_group_session_participants cgsp
    set daily_finished_at = coalesce(cgsp.daily_finished_at, now()),
        daily_finish_seconds = case
          when cgsp.daily_finish_seconds is null then v_elapsed_seconds
          else least(cgsp.daily_finish_seconds, v_elapsed_seconds)
        end,
        last_activity_at = now()
    where cgsp.group_session_id = v_group_session.id
      and cgsp.athlete_id = v_assignment.athlete_id;
  end if;

  select p.daily_pb_seconds into v_old_pb
  from public.profiles p
  where p.id = v_assignment.athlete_id;

  if v_old_pb is null or v_elapsed_seconds < v_old_pb then
    update public.profiles p
    set daily_pb_seconds = v_elapsed_seconds,
        daily_pb_updated_at = now(),
        updated_at = now()
    where p.id = v_assignment.athlete_id;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_assignment_progress_xp()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_assignment public.weekly_trick_assignments%rowtype;
  v_row public.assignment_progress%rowtype;
  v_old_date date;
  v_new_date date;
  v_date date;
  v_venue text;
  v_source_id text;
  v_done boolean;
  v_xp integer;
  v_reason text;
begin
  v_row := coalesce(new, old);

  select wta.* into v_assignment
  from public.weekly_trick_assignments wta
  where wta.id = v_row.assignment_id;

  if v_assignment.id is null then
    return coalesce(new, old);
  end if;

  if v_assignment.category = 'daily' then
    v_venue := coalesce(nullif(trim(v_assignment.venue), ''), 'default');
    v_old_date := case when tg_op in ('UPDATE','DELETE') then old.progress_date else null end;
    v_new_date := case when tg_op in ('INSERT','UPDATE') then new.progress_date else null end;

    for v_date in
      select distinct d
      from (values (v_old_date), (v_new_date)) as dates(d)
      where d is not null
    loop
      v_source_id := v_assignment.week_start::text || ':' || v_venue || ':' || v_date::text;
      select not exists (
        select 1
        from public.weekly_trick_assignments a
        left join public.assignment_progress ap on ap.assignment_id = a.id
        where a.athlete_id = v_assignment.athlete_id
          and a.week_start = v_assignment.week_start
          and a.category = 'daily'
          and coalesce(nullif(trim(a.venue), ''), 'default') = v_venue
          and ap.progress_date is distinct from v_date
      ) into v_done;

      perform public.sync_xp_award(
        v_assignment.athlete_id,
        'daily_complete',
        v_source_id,
        case when v_done then 35 else 0 end,
        'Completed full Daily Tricks list',
        v_assignment.id,
        null,
        'Daily Tricks list',
        v_venue,
        null,
        jsonb_build_object('date', v_date, 'venue', v_venue, 'week_start', v_assignment.week_start)
      );
    end loop;

    return coalesce(new, old);
  end if;

  if v_assignment.category in ('one_bang', 'dialled', 'bonus') then
    v_xp := case when v_assignment.category = 'bonus' then 250 else 35 end;
    v_reason := case when v_assignment.category = 'bonus' then 'Completed Bonus Trick' when v_assignment.category = 'dialled' then 'Landed Dialled trick' else 'Landed One Bang' end;

    perform public.sync_xp_award(
      v_assignment.athlete_id,
      v_assignment.category,
      v_assignment.id::text,
      case when tg_op <> 'DELETE' and new.completed_at is not null then v_xp else 0 end,
      v_reason,
      v_assignment.id,
      null,
      v_assignment.trick_name,
      v_assignment.venue,
      null,
      jsonb_build_object('week_start', v_assignment.week_start)
    );
  end if;

  return coalesce(new, old);
end;
$function$

CREATE OR REPLACE FUNCTION public.sync_xp_award(p_athlete_id uuid, p_source_type text, p_source_id text, p_xp integer, p_reason text, p_assignment_id uuid DEFAULT NULL::uuid, p_session_id uuid DEFAULT NULL::uuid, p_trick_name text DEFAULT ''::text, p_venue text DEFAULT ''::text, p_coach_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_before_level integer := 1; v_after_level integer := 1; v_old_xp integer := 0; v_delta integer := 0; v_progress jsonb := '{}'::jsonb;
begin
  if p_athlete_id is null or trim(coalesce(p_source_type,''))='' or trim(coalesce(p_source_id,''))='' then raise exception 'XP award is missing a rider or source'; end if;
  select coalesce(p.level,1) into v_before_level from public.profiles p where p.id = p_athlete_id;
  select coalesce(xl.xp,0) into v_old_xp from public.xp_ledger xl where xl.athlete_id=p_athlete_id and xl.source_type=p_source_type and xl.source_id=p_source_id;
  v_old_xp := coalesce(v_old_xp,0);
  if coalesce(p_xp,0)=0 then
    delete from public.xp_ledger xl where xl.athlete_id=p_athlete_id and xl.source_type=p_source_type and xl.source_id=p_source_id;
    v_delta := -v_old_xp;
  else
    insert into public.xp_ledger (athlete_id,source_type,source_id,xp,reason,assignment_id,session_id,trick_name,venue,coach_id,metadata,level_before,level_after)
    values (p_athlete_id,trim(p_source_type),trim(p_source_id),p_xp,coalesce(p_reason,''),p_assignment_id,p_session_id,coalesce(p_trick_name,''),coalesce(p_venue,''),p_coach_id,coalesce(p_metadata,'{}'::jsonb),v_before_level,v_before_level)
    on conflict (athlete_id, source_type, source_id) do update set xp=excluded.xp, reason=excluded.reason, assignment_id=excluded.assignment_id, session_id=excluded.session_id, trick_name=excluded.trick_name, venue=excluded.venue, coach_id=excluded.coach_id, metadata=excluded.metadata, updated_at=now();
    v_delta := p_xp - v_old_xp;
  end if;
  v_progress := public.sync_profile_xp(p_athlete_id);
  v_after_level := coalesce((v_progress->>'level')::integer, 1);
  update public.xp_ledger xl set level_before=v_before_level, level_after=v_after_level where xl.athlete_id=p_athlete_id and xl.source_type=p_source_type and xl.source_id=p_source_id;
  return v_progress || jsonb_build_object('athlete_id',p_athlete_id,'xp_delta',v_delta,'xp_awarded',greatest(v_delta,0),'xp_removed',greatest(-v_delta,0),'level_before',v_before_level,'level_after',v_after_level,'leveled_up',v_after_level>v_before_level,'level_badge',public.level_badge(v_after_level));
end;
$function$

CREATE OR REPLACE FUNCTION public.level_badge(p_level integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_level integer := least(50, greatest(1, coalesce(p_level, 1)));
  v_icons text[] := array['⌁','◉','⚙','▣','◒','🏁','✦','▰','◈','⌃','⌁','▬','🔗','♜','⚙','▰','◐','★','⚡','🚲','◇','◉','⚙','▣','∞','🚲','▰','★','♛','🔥','◉','⚡','⌁','»','✊','🚲','★','⚙','1','🚲','🚲','🔗','🚲','♛','◉','🔥','★','⚡','👑','🏆'];
  v_tone text := case when v_level >= 41 then 'red' when v_level >= 36 then 'purple' when v_level >= 31 then 'aqua' when v_level >= 21 then 'gold' when v_level >= 11 then 'silver' else 'bronze' end;
begin
  return jsonb_build_object('key','level-'||v_level::text,'type','level','level',v_level,'label','Level '||v_level::text||' Badge','icon',v_icons[v_level],'tone',v_tone,'description',case when v_level=50 then 'Elite JKCREW progression badge' when v_level>=41 then 'Pro-level progression badge' when v_level>=31 then 'Advanced progression badge' when v_level>=21 then 'Strong progression badge' when v_level>=11 then 'Building progression badge' else 'Foundation progression badge' end);
end;
$function$
